const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
/** Sweep coverage once per code point. Adjacent equal states merge into one mark. */
export function highlightHtml(text,matches=[]){const chars=Array.from(String(text)),n=chars.length,active=new Int32Array(n+1),quoted=new Int32Array(n+1);for(const match of matches){const a=Math.max(0,Math.min(n,match.range?.[0])),b=Math.max(0,Math.min(n,match.range?.[1]));if(!Number.isInteger(a)||!Number.isInteger(b)||b<=a)continue;active[a]++;active[b]--;const exclusions=(match.excludedRanges||[]).map(([from,to])=>[Math.max(a,from),Math.min(b,to)]).filter(([from,to])=>to>from).sort((x,y)=>x[0]-y[0]||x[1]-y[1]);let start=-1,end=-1;const add=()=>{if(start>=0){quoted[start]++;quoted[end]--;}};for(const [from,to]of exclusions){if(from<=end)end=Math.max(end,to);else{add();start=from;end=to;}}add();}const result=[];let coverage=0,quotation=0,start=0,previous=null;const append=(end,type)=>{if(end<=start)return;const value=escape(chars.slice(start,end).join(''));result.push(type?`<mark class="${type}">${value}</mark>`:value);};for(let i=0;i<n;i++){coverage+=active[i];quotation+=quoted[i];const type=coverage>0?(coverage===quotation?'quoted':'matched'):null;if(type!==previous){append(i,previous);start=i;previous=type;}}append(n,previous);return result.join('');}
export function evidencePreview(matches,limit=12){limit=Math.max(0,Math.floor(limit));if(!limit)return[];const unique=[],keys=new Set();for(const match of matches){const key=Array.isArray(match.range)?JSON.stringify([match.sourceId,match.range,match.citationStatus,match.excludedRanges||[]]):match;if(keys.has(key))continue;keys.add(key);unique.push(match);}const first=[],used=new Set(),sources=new Set();for(const match of unique){if(sources.has(match.sourceId))continue;first.push(match);sources.add(match.sourceId);used.add(match);if(first.length>=limit)return first;}for(const match of unique){if(used.has(match))continue;first.push(match);if(first.length>=limit)break;}return first;}
